from src.nodes.base import BaseNode
from src.runtime.lookdev import get_lookdev_patterns
import json

class Hou_Mcp_Lookdev_Patterns(BaseNode):
    name = "hou_mcp_lookdev_patterns"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("query",       "string", widget_type="text", default="")
        self.add_input("environment", "string", widget_type="text", default="")
        self.add_input("asset_json",  "string", widget_type="text", default="")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("patterns_json",    "string")
        self.add_output("pattern_count",    "int")
        self.add_output("top_pattern_name", "string")

    async def execute(self, inputs):
        query       = str(inputs.get("query",       "") or "")
        environment = str(inputs.get("environment", "") or "")
        asset_json  = str(inputs.get("asset_json",  "") or "")
        try:
            lib = get_lookdev_patterns()
            if asset_json.strip():
                try:
                    asset_dict = json.loads(asset_json)
                except Exception:
                    asset_dict = {}
                patterns = lib.rank_patterns(asset_dict if isinstance(asset_dict, dict) else {})
            else:
                patterns = lib.search_patterns(query=query, environment=environment)
            top_name = patterns[0].name if patterns else ""
            self.log_info(f"Lookdev patterns: found {len(patterns)} pattern(s). Top: {top_name!r}.")
            return {
                "patterns_json":    json.dumps([p.to_dict() for p in patterns], sort_keys=True, default=str),
                "pattern_count":    len(patterns),
                "top_pattern_name": top_name,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Lookdev patterns query failed: {exc}")
            return {"patterns_json": "[]", "pattern_count": 0, "top_pattern_name": "", "exec_out": True}

def register_node():
    return Hou_Mcp_Lookdev_Patterns
